import { ProductRepository } from '../domain/ProductRepository';
import { ProductResponse } from './dto/ProductResponse';

export class GetStockLevelsUseCase {
  constructor(private productRepository: ProductRepository) {}

  execute(): ProductResponse[] {
    const products = this.productRepository.findAll();
    return products.map((product) => ({
      id: product.id,
      name: product.name,
      availableStock: product.getAvailableStock().value,
      reservedStock: product.getReservedStock().value,
      totalStock: product.getTotalStock().value,
    }));
  }
}

