import { OrderStateType } from '../domain/OrderState';
import { OrderRepository } from '../domain/OrderRepository';

export class UpdateOrderStateUseCase {
  constructor(private orderRepository: OrderRepository) {}

  execute(orderId: any, newState: any): void {
    const idStr = Array.isArray(orderId) ? orderId[0] : orderId;
    const order = this.orderRepository.findById(idStr);
    if (!order) {
      throw new Error(`Order ${idStr} not found`);
    }

    let stateStr = '';
    if (Array.isArray(newState)) {
      stateStr = newState[0]?.toString() || '';
    } else if (typeof newState === 'string') {
      stateStr = newState;
    }
    order.transitionTo(stateStr as OrderStateType);
    this.orderRepository.save(order);
  }
}

